import logging


class RMODSessionLogger:
    def __init__(self, name, log_path):
        self._logger = logging.getLogger(name=name)
        self._logger.setLevel(logging.DEBUG)
        self._handler = logging.FileHandler(log_path)
        self._logger.addHandler(self._handler)
        common_format = "%(asctime)s - %(message)s"
        self.write_formatter = logging.Formatter(f"> {common_format}")
        self.read_formatter = logging.Formatter(f"< {common_format}")
        self.debug_formatter = logging.Formatter(f"~ {common_format}")

    def log_write(self, message):
        self._handler.setFormatter(self.write_formatter)
        self._logger.info(repr(message))

    def log_read(self, message):
        self._handler.setFormatter(self.read_formatter)
        self._logger.info(repr(message))

    def log_debug(self, message):
        self._handler.setFormatter(self.debug_formatter)
        self._logger.debug(repr(message))
